MASK=(1<<64)-1; LOW=0x7f7f7f7f7f7f7f7f; HIGH=0x8080808080808080
def old(word,code):
 d=word^((code*0x0101010101010101)&MASK)
 return (~(((((d&LOW)+LOW)&MASK)|d|LOW))&HIGH)&MASK
def floor(word,code):
 d=word^((code*0x0101010101010101)&MASK)
 return sum(0x80<<(8*i) for i in range(8) if ((d>>(8*i))&255)==0)
for code in (0,1,127,128,255,256,0x123456789abcdef0,MASK):
 rep=(code*0x0101010101010101)&MASK
 for lane in range(8):
  for byte in range(256):
   word=rep^(byte<<(8*lane)); assert old(word,code)==floor(word,code)
